    re.I,
)


def _biz_bullet_count(text: str) -> int:
    n = 0
    for line in (text or "").splitlines():
        s = line.strip()
        if not s.startswith("- "):
            continue
        body = s[2:].strip()
        if _BIZ_RE.search(body):
            n += 1
    return n


def _looks_ops_mirror_shell(text: str) -> bool:
    t = text or ""
    if "ops-mirror" in t or "流水偏空警告" in t or "暂无手写流水" in t:
        if _biz_bullet_count(t) == 0:
            return True
    return False

